<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import TaskStepper from '../components/TaskStepper.vue'; import TaxonomyTree from '../components/TaxonomyTree.vue'; import {api,type Task,type Taxonomy} from '../services/api'
const route=useRoute(),router=useRouter(),task=ref<Task|null>(null),trees=ref<Taxonomy[]>([]),selected=ref(''),error=ref(''),busy=ref(false); const current=computed(()=>trees.value.find(x=>x.status==='draft')||trees.value.find(x=>x.status==='approved'))
onMounted(async()=>{try{task.value=await api.task(String(route.params.id));trees.value=await api.taxonomies(String(route.params.id))}catch(e){error.value=String(e)}})
async function approve(){if(!task.value||!current.value)return;busy.value=true;try{if(current.value.status==='draft'){await api.approveTaxonomy(task.value.id,current.value.taxonomy_id,task.value.revision,current.value.tree_hash)}await router.push(`/tasks/${task.value.id}/review`)}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><section class="page"><TaskStepper :current="2"/><header class="page-heading"><div><p class="eyebrow">TAXONOMY</p><h1>确认分类结构</h1><p class="lead">分类树按整理区域冻结；此时仍不会移动文件。</p></div></header><p v-if="error" class="notice danger-notice">{{error}}</p><div v-if="current" class="taxonomy-layout"><section class="state-card"><p><b>{{current.nodes.length}}</b> 个节点 · v{{current.version}} · {{current.status}}</p><TaxonomyTree :taxonomy="current" :selected="selected" @select="selected=$event"/></section><aside class="state-card"><h2>覆盖与约束</h2><p>最多 {{task?.settings.max_depth}} 级，同级最多 {{task?.settings.max_siblings}} 个目录。</p><p>tree hash</p><code>{{current.tree_hash}}</code><p>模板样本用于规划，不代表已阅读全文。</p></aside></div><div v-else class="state-card">尚无分类树；请先完成分析或选择纯类型模板。</div><footer class="action-bar"><span>确认会冻结当前 tree hash；原文件不变</span><button class="primary-button" :disabled="!current||busy" @click="approve">{{busy?'正在确认…':'确认分类结构并继续'}}</button></footer></section></template>
